package mrpapermoon.whisper.serviceimport android.content.Contextimport com.google.android.gms.nearby.connection.AdvertisingOptionsimport com.google.android.gms.nearby.connection.ConnectionInfoimport com.google.android.gms.nearby.connection.ConnectionLifecycleCallbackimport com.google.android.gms.nearby.connection.ConnectionResolutionimport com.google.android.gms.nearby.connection.DiscoveredEndpointInfoimport com.google.android.gms.nearby.connection.DiscoveryOptionsimport com.google.android.gms.nearby.connection.EndpointDiscoveryCallbackimport com.google.android.gms.nearby.connection.Payloadimport com.google.android.gms.nearby.connection.PayloadCallbackimport com.google.android.gms.nearby.connection.PayloadTransferUpdateimport com.google.android.gms.nearby.connection.Strategyimport io.github.oshai.kotlinlogging.KotlinLoggingimport kotlinx.coroutines.Dispatchersimport kotlinx.coroutines.channels.SendChannelimport kotlinx.coroutines.currentCoroutineContextimport kotlinx.coroutines.flow.flowimport kotlinx.coroutines.isActiveimport kotlinx.coroutines.withContextimport mrpapermoon.whisper.tools.logResultimport java.io.IOExceptionimport java.util.concurrent.ConcurrentHashMapimport java.util.concurrent.CopyOnWriteArrayListimport java.util.concurrent.CopyOnWriteArraySetinternal class NetworkConnectionsWrapperImpl(	actor: SendChannel<Event>,	context: Context,	private val serviceId: String,	private val uuid: String,) : NetworkConnectionsWrapper(actor, context) {	override val activeEndpoints = CopyOnWriteArrayList<String>()	private val logger = KotlinLogging.logger {}	suspend fun startNetwork() {		val strategy = Strategy.P2P_CLUSTER		withContext(Dispatchers.IO) {			logger.info { "startDiscovery" }			val discoveryOptions = DiscoveryOptions.Builder()				.setStrategy(strategy)				.build()			connectionsClient.startDiscovery(				serviceId,				InternalEndpointDiscoveryCallback(),				discoveryOptions,			)				.logResult("Discovery", uuid)		}		withContext(Dispatchers.IO) {			logger.info { "startAdvertising" }			val advertisingOptions = AdvertisingOptions.Builder()				.setStrategy(strategy)				.build()			connectionsClient.startAdvertising(				uuid,				serviceId,				InternalConnectionLifecycleCallback(),				advertisingOptions,			)				.logResult("Advertising", uuid)		}	}	override fun stopNetwork() {		connectionsClient.stopDiscovery()		logger.debug { "stopDiscovery" }		connectionsClient.stopAdvertising()		logger.debug { "stopAdvertising" }		connectionsClient.stopAllEndpoints()		logger.debug { "stopAllEndpoints" }		super.stopNetwork()		activeEndpoints.clear()	}	private inner class InternalConnectionLifecycleCallback : ConnectionLifecycleCallback() {		override fun onConnectionInitiated(endpointId: String, connectionInfo: ConnectionInfo) {			logger.debug { "onConnectionInitiated(endpointId: $endpointId, connectionInfo: ${connectionInfo.dumpString()})" }			connectionsClient.acceptConnection(endpointId, InternalPayloadCallback())				.logResult("Accept connection", endpointId, connectionInfo)		}		override fun onConnectionResult(endpointId: String, result: ConnectionResolution) {			val status = result.status			logger.debug { "onConnectionResult(endpointId: $endpointId, status: $status)" }			if (!status.isSuccess) {				if (!status.isCanceled && !status.isInterrupted) {					logger.warn { "OnConnectionResult failed: statusCode >${status.statusCode} statusMessage >${status.statusMessage}" }				}				return			}			activeEndpoints += endpointId			sendEvent(Event.NewConnection(endpointId))		}		override fun onDisconnected(endpointId: String) {			logger.debug { "OnDisconnect(endpointId: $endpointId)" }			activeEndpoints -= endpointId			sendEvent(Event.DropConnection(endpointId))		}	}	private inner class InternalEndpointDiscoveryCallback : EndpointDiscoveryCallback() {		private val discoveryConnections = CopyOnWriteArraySet<String>()		override fun onEndpointFound(			endpointId: String,			info: DiscoveredEndpointInfo,		) {			logger.debug { "onEndpointFound(endpointId: $endpointId, info: ${info.dumpString()})" }			if (discoveryConnections.contains(endpointId) || activeEndpoints.contains(endpointId)) {				logger.warn { "Endpoint $endpointId is already connected" }				return			}			discoveryConnections += endpointId			connectionsClient.requestConnection(uuid, endpointId, InternalConnectionLifecycleCallback())				.addOnCompleteListener {					discoveryConnections -= endpointId				}				.logResult("request connection", endpointId, info)		}		override fun onEndpointLost(endpointId: String) {			logger.debug { "onEndpointLost(endpointId: $endpointId)" }			discoveryConnections -= endpointId		}	}	private inner class InternalPayloadCallback : PayloadCallback() {		private val streamMap = ConcurrentHashMap<Long, Payload>()		override fun onPayloadReceived(			endpointId: String,			payload: Payload,		) {			logger.debug { "onPayloadReceived(endpointId: $endpointId, payload: $payload)" }			when (payload.type) {				Payload.Type.BYTES -> {					sendEvent(Event.OnMessage(payload.asBytes()!!))				}				Payload.Type.STREAM -> {					streamMap[payload.id] = payload				}				else -> {					connectionsClient.rejectConnection(endpointId)				}			}		}		override fun onPayloadTransferUpdate(endpointId: String, update: PayloadTransferUpdate) {			logger.debug { "onPayloadTransferUpdate(endpointId: $endpointId, update: ${update.dumpString()})" }			val payloadId = update.payloadId			val payload = streamMap[payloadId] ?: return			when (update.status) {				PayloadTransferUpdate.Status.SUCCESS -> {					val byteFlow = flow {						payload.asStream()?.asInputStream()?.use { stream ->							val available = stream.available()							while (currentCoroutineContext().isActive && available > 0) {								val buffer = ByteArray(available)								runCatching {									stream.read(buffer)								}									.onFailure {										if (it is IOException) {											logger.error(it) { "Error reading stream" }											connectionsClient.rejectConnection(endpointId)										} else {											throw it										}									}									.onSuccess {										emit(buffer)									}							}						}					}					sendEvent(Event.OnStream(byteFlow))				}				PayloadTransferUpdate.Status.IN_PROGRESS -> return			}			streamMap.remove(payloadId)		}	}}private fun ConnectionInfo.dumpString(): String = "ConnectionInfo(endpointName=$endpointName, isIncomingConnection=$isIncomingConnection)"private fun DiscoveredEndpointInfo.dumpString(): String = "DiscoveredEndpointInfo(serviceId: $serviceId, endpointName: $endpointName)"private fun PayloadTransferUpdate.dumpString(): String = "PayloadTransferUpdate(payloadId=$payloadId, status=$status, bytesTransferred=$bytesTransferred, totalBytes=$totalBytes)"